let language='en';try{const saved=localStorage.getItem('beijing-map-language');language=saved==='zh'||saved==='en'?saved:(navigator.language||'').startsWith('zh')?'zh':'en';}catch{}
function tr(key,args={}){return(I18N[language][key]??I18N.en[key]??key).replace(/\{(\w+)\}/g,(_,name)=>String(args[name]??''));}
function applyLanguage(){document.documentElement.lang=language==='zh'?'zh-CN':'en';document.title=tr('title');document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=tr(e.dataset.i18n));document.querySelectorAll('[data-i18n-html]').forEach(e=>e.innerHTML=tr(e.dataset.i18nHtml));document.querySelectorAll('[data-i18n-aria]').forEach(e=>e.setAttribute('aria-label',tr(e.dataset.i18nAria)));document.querySelectorAll('[data-language]').forEach(e=>{const active=e.dataset.language===language;e.classList.toggle('active',active);e.setAttribute('aria-pressed',active);});}
